class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        ops = 0
        alphabet = "abcdfhosmyx"
        i = 0
        while i < len(word) - 1:
            if word[i] == word[i + 1] or abs(ord(word[i]) - ord(word[i + 1])) == 1:
                for letter in alphabet:
                    if i > 0 and (letter == word[i - 1] or abs(ord(letter) - ord(word[i - 1])) == 1):
                        continue
                    if i + 2 < len(word) and (letter == word[i + 2] or abs(ord(letter) - ord(word[i + 2])) == 1):
                        continue
                    word = word[:i + 1] + letter + word[i + 2:]
                    ops += 1
                    break
            else:
                i += 1
        return ops
